    '/clothing/sweatshirts-and-jackets/arborwear-safety-yellow-tech-double-thick-pullover-sweatshirt/' => 
    array (
      'path' => '/clothing/sweatshirts-and-jackets/arborwear-safety-yellow-tech-double-thick-pullover-sweatshirt/',
      'category' => '/clothing/sweatshirts-and-jackets/',
      'name' => 'Arborwear Tech Double Thick Pullover Sweatshirt, Safety Yellow',
      'brand' => 'arborwear',
      'brand_name' => 'Arborwear',
