      'path' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/oregon-chainsaw-bar-325-x-050/',
      'category' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/',
      'name' => 'Oregon Chainsaw Bar, .325" x .050"',
      'brand' => 'oregon',
