    '/safety/communication/3m-peltor-lite-com-frs/' => 
    array (
      'path' => '/safety/communication/3m-peltor-lite-com-frs/',
      'category' => '/safety/communication/',
      'name' => '3M Peltor LiteCom FRS Headset',
