        13 => '/climbing/climbing-gear/carabiners-and-hardware/screw-gate-carabiners/smc-large-heat-treated-steel-screw-locking-carabiner/',
        14 => '/climbing/climbing-gear/carabiners-and-hardware/snap-hooks/aluminum-double-locking-snap-hook/',
        15 => '/climbing/climbing-gear/carabiners-and-hardware/snap-hooks/petzl-eashook-open-rope-snap/',
        16 => '/climbing/climbing-gear/carabiners-and-hardware/snap-hooks/steel-locking-rope-snap/',
        17 => '/saddle-storage/isc-nessie-lanyard-management-clip/',
        18 => '/saddle-storage/rock-exotica-transporter-xl/',
        19 => '/shop-all/polymer-hook-with-standard-end/',
