        2 => '/cutting-and-pruning/hand-saws-and-scabbards/silky-gomtaro-pro-sentei-300mm-hand-saw/',
        3 => '/cutting-and-pruning/hand-saws-and-scabbards/silky-gunfighter-professional-saw-330mm-handsaw/',
        4 => '/cutting-and-pruning/hand-saws-and-scabbards/silky-sugoi/',
        5 => '/cutting-and-pruning/hand-saws-and-scabbards/silky-zubat-13-curved-hand-saw/',
        6 => '/cutting-and-pruning/pole-saws-and-scabbards/20-nobasu-4-section-telescoping-aluminum-polesaw/',
        7 => '/cutting-and-pruning/pole-saws-and-scabbards/jameson-ls-kit-pruner-pole-saw-and-poles/',
        8 => '/cutting-and-pruning/pole-saws-and-scabbards/marvin-cast-saw-head/',
        9 => '/cutting-and-pruning/poles-and-kits/6-foam-filled-poles/',
        10 => '/cutting-and-pruning/poles-and-kits/jameson-8-hollow-core-pole/',
