    '/cmi/' => 
    array (
      'slug' => 'cmi',
      'path' => '/cmi/',
      'name' => 'CMI',
      'keyword' => 'cmi climbing gear',
      'title' => 'CMI Rescue & Climbing Hardware',
      'meta' => 'CMI climbing and rescue hardware for arborists: anchor slings, pulleys, carabiners and rope grabs. Tough rescue-world gear for tree climbing and rigging.',
      'intro' => 'CMI makes climbing and rescue hardware including anchor slings, pulleys and carabiners. Arborists use CMI gear for anchors and climbing setups.',
      'about' => 
      array (
        0 => 'CMI builds gear with roots in rescue work, where hardware has to be simple and tough. For tree work, CMI anchor slings are a common way to set a basal or canopy anchor, and their pulleys and rope grabs fit into climbing and haul systems.',
        1 => 'Check ratings and rope compatibility for every piece, follow the manufacturer\'s instructions, and inspect slings and hardware before every use.',
      ),
      'known_for' => 
      array (
        0 => 'Anchor slings',
        1 => 'Pulleys',
        2 => 'Carabiners',
        3 => 'Rope grabs',
      ),
      'aliases' => 
      array (
      ),
      'products' => 
      array (
        0 => '/climbing/climbing-gear/friction-savers/cmi-anchor-sling/',
        1 => '/climbing/climbing-gear/micro-pulleys/cmi-micro-rescue-pulley/',
        2 => '/climbing/climbing-gear/swivels/cmi-california-swivel/',
        3 => '/foot-ascenders-and-foot-loops/cmi-foot-ascender/',
        4 => '/rigging/blocks-and-other-hardware/rigging-blocks/cmi-5-8-steel-arborist-block/',
        5 => '/rigging/rigging-slings/light-duty-slings/cmi-heavy-duty-loop-runners/',
      ),
